ValidationRule.errorConditionFormula:
AND(
    ISCHANGED(Estado__c),
    NOT($User.Alias = 'amet'),
    NOT($Profile.Name = 'USC'),
    NOT($Profile.Name == 'System Administrator'),
    CASE(Estado__c,
        /* BLOCK BACKWARDS TO OPEN: If moving TO Open, it must have been null/new */
        "OPEN", IF(ISBLANK(PRIORVALUE(Estado__c)), 0, 1),

        /* WORK: Must come from OPEN */
        "WORK", IF(ISPICKVAL(PRIORVALUE(Estado__c), "OPEN"), 0, 1),

        /* CHECK: Must come from WORK */
        "CHECK", IF(ISPICKVAL(PRIORVALUE(Estado__c), "WORK"), 0, 1),

        /* REVIEW: Must come from CHECK */
        "REVIEW", IF(ISPICKVAL(PRIORVALUE(Estado__c), "CHECK"), 0, 1),

        /* APPROVED: Must come from REVIEW or REJECTED */
        "APPROVED", IF(OR(ISPICKVAL(PRIORVALUE(Estado__c), "REVIEW"),
                          ISPICKVAL(PRIORVALUE(Estado__c), "REJECTED")), 0, 1),

        /* REJECTED: Must come from REVIEW or APPROVED */
        "REJECTED", IF(OR(ISPICKVAL(PRIORVALUE(Estado__c), "REVIEW"),
                          ISPICKVAL(PRIORVALUE(Estado__c), "APPROVED")), 0, 1),

        /* CLOSED: Must come from APPROVED or REJECTED */
        "CLOSED", IF(OR(ISPICKVAL(PRIORVALUE(Estado__c), "APPROVED"), 
                        ISPICKVAL(PRIORVALUE(Estado__c), "REJECTED")), 0, 1),

        0
    ) = 1
)
